package com.medflow.auth;
import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import com.medflow.auth.domain.*; import com.medflow.auth.repository.UserAccountRepository; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.test.web.servlet.MockMvc; import static org.hamcrest.Matchers.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class AuthControllerIntegrationTest {
 @Autowired MockMvc mvc; @Autowired ObjectMapper json; @Autowired UserAccountRepository users; @Autowired PasswordEncoder passwords;
 @BeforeEach void clean(){users.deleteAll();}
 private String patient(){return "{\"fullName\":\"Synthetic Patient\",\"email\":\"patient@example.test\",\"password\":\"SafePass123!\"}";}
 private void register()throws Exception{mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content(patient())).andExpect(status().isCreated());}
 @Test void validRegistrationIsPatientAndDoesNotExposePassword()throws Exception{mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content(patient())).andExpect(status().isCreated()).andExpect(jsonPath("$.role").value("PATIENT")).andExpect(jsonPath("$.passwordHash").doesNotExist());}
 @Test void duplicateEmailRejected()throws Exception{register();mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content(patient())).andExpect(status().isConflict());}
 @Test void invalidEmailRejected()throws Exception{mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content(patient().replace("patient@example.test","bad"))).andExpect(status().isBadRequest());}
 @Test void weakPasswordRejected()throws Exception{mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content(patient().replace("SafePass123!","weak"))).andExpect(status().isBadRequest());}
 @Test void privilegedRoleCannotBeMassAssigned()throws Exception{String request=patient().replace("}",",\"role\":\"ADMIN\"}");mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content(request)).andExpect(status().isCreated()).andExpect(jsonPath("$.role").value("PATIENT"));}
 @Test void meWithoutTokenIsUnauthorized()throws Exception{mvc.perform(get("/api/auth/me")).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.message").value("Authentication is required"));}
 @Test void loginAndMeWithTokenSucceed()throws Exception{register();String body=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"PATIENT@EXAMPLE.TEST\",\"password\":\"SafePass123!\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.accessToken",not(emptyString()))).andReturn().getResponse().getContentAsString();JsonNode response=json.readTree(body);mvc.perform(get("/api/auth/me").header("Authorization","Bearer "+response.get("accessToken").asText())).andExpect(status().isOk()).andExpect(jsonPath("$.email").value("patient@example.test"));}
 @Test void incorrectPasswordRejected()throws Exception{register();mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"patient@example.test\",\"password\":\"WrongPass123!\"}")).andExpect(status().isUnauthorized());}
 @Test void unknownAccountRejectedSafely()throws Exception{mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"unknown@example.test\",\"password\":\"SafePass123!\"}")).andExpect(status().isUnauthorized()).andExpect(jsonPath("$.message").value("Invalid email or password"));}
 @Test void nonAdminCannotCreateStaff()throws Exception{register();String token=login("patient@example.test","SafePass123!");mvc.perform(post("/api/auth/staff").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(staff("doctor@example.test","DOCTOR"))).andExpect(status().isForbidden());}
 @Test void adminCreatesDoctorWithEncodedPasswordAndDoctorLoginHasRole()throws Exception{String adminToken=createAdminAndLogin();mvc.perform(post("/api/auth/staff").header("Authorization","Bearer "+adminToken).contentType(MediaType.APPLICATION_JSON).content(staff("doctor@example.test","DOCTOR"))).andExpect(status().isCreated()).andExpect(jsonPath("$.role").value("DOCTOR")).andExpect(jsonPath("$.passwordHash").doesNotExist());var doctor=users.findByEmail("doctor@example.test").orElseThrow();Assertions.assertNotEquals("DoctorPass123!",doctor.getPasswordHash());Assertions.assertTrue(passwords.matches("DoctorPass123!",doctor.getPasswordHash()));String body=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\"doctor@example.test\",\"password\":\"DoctorPass123!\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.user.role").value("DOCTOR")).andExpect(jsonPath("$.accessToken",not(emptyString()))).andReturn().getResponse().getContentAsString();String token=json.readTree(body).get("accessToken").asText();JsonNode payload=json.readTree(java.util.Base64.getUrlDecoder().decode(token.split("\\.")[1]));Assertions.assertEquals("DOCTOR",payload.get("role").asText());Assertions.assertEquals(doctor.getId().toString(),payload.get("sub").asText());}
 @Test void adminCannotCreateAnotherAdminThroughStaffEndpoint()throws Exception{mvc.perform(post("/api/auth/staff").header("Authorization","Bearer "+createAdminAndLogin()).contentType(MediaType.APPLICATION_JSON).content(staff("second-admin@example.test","ADMIN"))).andExpect(status().isBadRequest());}
 private String staff(String email,String role){return "{\"fullName\":\"Synthetic Doctor\",\"email\":\""+email+"\",\"password\":\"DoctorPass123!\",\"role\":\""+role+"\"}";}
 private String createAdminAndLogin()throws Exception{UserAccount admin=new UserAccount();admin.setFullName("Synthetic Admin");admin.setEmail("admin@example.test");admin.setPasswordHash(passwords.encode("AdminPass123!"));admin.setRole(Role.ADMIN);admin.setEnabled(true);users.saveAndFlush(admin);return login("admin@example.test","AdminPass123!");}
 private String login(String email,String password)throws Exception{String body=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\""+password+"\"}")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();return json.readTree(body).get("accessToken").asText();}
}
